{
  "name": "@inference/trace-opencode",
  "version": "0.1.13",
  "type": "module",
  "description": "Automatically trace OpenCode coding sessions to Catalyst by Inference.net. Captures per-turn agent traces with LLM calls, tool executions, and token usage as OpenInference-shaped OpenTelemetry spans.",
  "homepage": "https://inference.net",
  "keywords": [
    "opencode",
    "catalyst",
    "inference",
    "llm",
    "agents",
    "observability",
    "openinference",
    "opentelemetry",
    "tracing"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": ["README.md", "dist"],
  "sideEffects": false,
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.build.json",
    "prepack": "bun run build",
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@inference/tracing": "^0.1.0",
    "@opentelemetry/api": "1.9.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.11 <2.0.0",
    "@opencode-ai/sdk": ">=1.15.11 <2.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode-ai/sdk": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.15.11",
    "@opencode-ai/sdk": "1.15.11",
    "@opentelemetry/sdk-trace-base": "2.2.0",
    "@opentelemetry/sdk-trace-node": "2.2.0",
    "@types/node": "22.19.17",
    "bun-types": "1.3.13",
    "typescript": "5.9.3"
  }
}
